  it("usage→ledger 窗口不可见半成品，IN_PROGRESS 使关账 fail-close 直到原子 finalize", async () => {
    const fixture = await seedSettlementFixture(
      "atomic", { status: "IN_PROGRESS", createUsage: false },
    );
